"""Presubmit checks for //third_party/protobuf.

Chromium maintains a copy of upstream protobuf in //third_party/protobuf along
with local modifications. Every local modification is stored in two places:
  1. Applied directly to the source tree under src/ or python/.
  2. Recorded as a top-level patch file in patches/NNNN-name.patch, with a
     matching '- NNNN-name.patch' entry under 'Description of the patches:' in
     README.chromium (and optionally a companion patches/NNNN-name.md note).

Because the roll procedure replaces //third_party/protobuf with a fresh upstream
archive and replays patches/*.patch, any local source change that is missing
from patches/ will be silently lost on the next roll (https://crbug.com/568001675).

This presubmit module enforces fast, offline invariants on every change touching
//third_party/protobuf:
  - CheckPatchInventoryInSync: top-level patches/*.patch files and the
    'Description of the patches:' section of README.chromium match 1-to-1.
  - CheckCompanionMarkdownFiles: every 'patches/NNNN-name.md' referenced in
    README.chromium exists on disk, and every top-level patches/*.md file has a
    matching patches/NNNN-name.patch file.
  - CheckNoPatchRejectOrOrigFiles: no leftover *.rej or *.orig files from a
    failed or fuzzy patch application remain under //third_party/protobuf.
  - CheckSourceModifiedWithoutPatch: changes to src/ or python/ (excluding files
    generated by gen_extra_chromium_files.py) prompt a warning when no top-level
    patches/*.patch file is part of the change.
  - CheckPresubmitUnitTests: runs unit tests in //third_party/protobuf.
"""

PRESUBMIT_VERSION = '2.0.0'

_README_FILENAME = 'README.chromium'
_PATCHES_DIRECTORY_NAME = 'patches'
_PATCHES_SECTION_HEADER = 'Description of the patches:'

# Roll instructions in README.chromium use 'patches/NNNN-name.md' as a literal
# placeholder example in prose; it does not refer to a real file on disk.
_INSTRUCTIONAL_PLACEHOLDER_MARKDOWN = 'NNNN-name.md'

# Files under src/ and python/ regenerated by gen_extra_chromium_files.py during
# roll step 4 using Chromium's patched protoc. These files legitimately differ
# from upstream without a corresponding patch file in patches/.
_BOOTSTRAP_GENERATED_FILES = frozenset({
    'src/google/protobuf/descriptor.pb.h',
    'src/google/protobuf/descriptor.pb.cc',
    'src/google/protobuf/compiler/plugin.pb.h',
    'src/google/protobuf/compiler/plugin.pb.cc',
    'python/google/protobuf/descriptor_pb2.py',
    'python/google/protobuf/compiler/plugin_pb2.py',
    'python/google/protobuf/internal/python_edition_defaults.py',
})


def _RelativePathInProtobuf(input_api, affected_file):
    """Returns affected_file's POSIX path relative to //third_party/protobuf.

    Args:
      input_api: The depot_tools presubmit InputApi instance.
      affected_file: An AffectedFile (or MockAffectedFile) from the change.

    Returns:
      A forward-slash relative path such as 'src/google/protobuf/message.h', or
      None if affected_file lies outside //third_party/protobuf.
    """
    protobuf_directory = input_api.os_path.abspath(
        input_api.PresubmitLocalPath())
    absolute_path = input_api.os_path.abspath(
        affected_file.AbsoluteLocalPath())
    try:
        common_prefix = input_api.os_path.commonpath(
            [protobuf_directory, absolute_path])
    except ValueError:
        return None
    if common_prefix != protobuf_directory or absolute_path == protobuf_directory:
        return None
    relative_path = input_api.os_path.relpath(
        absolute_path, protobuf_directory)
    return relative_path.replace('\\', '/')


def _TopLevelPatchesFilename(relative_path):
    """Returns the filename if relative_path is directly in patches/, else None.

    Upstream protobuf ships its own Bazel module patches in subdirectories such
    as patches/protobuf_v25/*.patch. Chromium stores its patches directly in
    patches/ without subdirectories, so any path containing a second '/' belongs
    to upstream and must be ignored.

    Args:
      relative_path: A POSIX path relative to //third_party/protobuf, or None.

    Returns:
      The bare filename (for example '0004-fix-shared-library-exports.patch') if
      relative_path is a direct child of patches/, or None otherwise.
    """
    if relative_path is None:
        return None
    patches_prefix = _PATCHES_DIRECTORY_NAME + '/'
    if not relative_path.startswith(patches_prefix):
        return None
    filename_in_patches = relative_path[len(patches_prefix):]
    if not filename_in_patches or '/' in filename_in_patches:
        return None
    return filename_in_patches


def _IsTopLevelPatchFile(relative_path):
    """Returns True if relative_path is a top-level patches/*.patch file."""
    filename = _TopLevelPatchesFilename(relative_path)
    return filename is not None and filename.endswith('.patch')


def _IsProtobufSourceFileRequiringPatch(relative_path):
    """Returns True if relative_path is a non-generated src/ or python/ file."""
    if relative_path is None:
        return False
    is_source_or_python = (
        relative_path.startswith('src/')
        or relative_path.startswith('python/'))
    return (is_source_or_python
            and relative_path not in _BOOTSTRAP_GENERATED_FILES)


def _IsPatchRejectOrBackupFile(filename):
    """Returns True if filename is a leftover .rej or .orig file from patch."""
    return filename.endswith(('.rej', '.orig'))


def _ReadReadmeLines(input_api):
    """Returns the lines of //third_party/protobuf/README.chromium, or None."""
    readme_path = input_api.os_path.join(
        input_api.PresubmitLocalPath(), _README_FILENAME)
    if not input_api.os_path.isfile(readme_path):
        return None
    return input_api.ReadFile(readme_path).splitlines()


def _ListTopLevelFilesInPatchesDirectory(input_api):
    """Returns the set of filenames directly under //third_party/protobuf/patches/.

    Subdirectories under patches/ (such as upstream's patches/protobuf_v25/) are
    excluded because input_api.os_path.isfile is False for directories.
    """
    patches_directory = input_api.os_path.join(
        input_api.PresubmitLocalPath(), _PATCHES_DIRECTORY_NAME)
    if not input_api.os_path.isdir(patches_directory):
        return set()
    return {
        entry_name for entry_name in input_api.os_listdir(patches_directory)
        if input_api.os_path.isfile(
            input_api.os_path.join(patches_directory, entry_name))
    }


def _ParseDocumentedPatchEntries(input_api, readme_lines):
    """Extracts '- NNNN-name.patch' entries from README.chromium.

    Args:
      input_api: The depot_tools presubmit InputApi instance.
      readme_lines: Sequence of lines from README.chromium.

    Returns:
      The ordered list of patch filenames from top-level '- <filename>' bullets
      following the 'Description of the patches:' heading, or None if that
      heading is absent.
    """
    section_header_index = None
    for line_index, line in enumerate(readme_lines):
        if line.strip() == _PATCHES_SECTION_HEADER:
            section_header_index = line_index
            break

    if section_header_index is None:
        return None

    # Patch entries sit at column 0 ('- 0004-fix-shared-library-exports.patch'),
    # whereas prose inside a patch description is indented by at least 2 spaces.
    top_level_bullet_pattern = input_api.re.compile(r'^-\s+(\S+)\s*$')
    documented_entries = []
    for line in readme_lines[section_header_index + 1:]:
        match = top_level_bullet_pattern.match(line)
        if match is not None:
            documented_entries.append(match.group(1))

    return documented_entries


def _ParseReferencedCompanionMarkdownFiles(input_api, readme_lines):
    """Extracts 'NNNN-name.md' filenames referenced as 'patches/NNNN-name.md'.

    Args:
      input_api: The depot_tools presubmit InputApi instance.
      readme_lines: Sequence of lines from README.chromium.

    Returns:
      A set of markdown filenames (without the 'patches/' prefix) referenced in
      README.chromium, excluding the instructional 'NNNN-name.md' placeholder.
    """
    companion_markdown_pattern = input_api.re.compile(
        r'\bpatches/([A-Za-z0-9_.-]+\.md)\b')
    referenced_markdown_files = set()
    for line in readme_lines:
        for match in companion_markdown_pattern.finditer(line):
            markdown_filename = match.group(1)
            if markdown_filename != _INSTRUCTIONAL_PLACEHOLDER_MARKDOWN:
                referenced_markdown_files.add(markdown_filename)
    return referenced_markdown_files


def _FindDuplicateEntries(entries):
    """Returns a sorted list of items that appear more than once in entries."""
    seen = set()
    duplicates = set()
    for entry in entries:
        if entry in seen:
            duplicates.add(entry)
        seen.add(entry)
    return sorted(duplicates)


def _FormatPatchInventorySyncItems(
        undocumented_patch_files,
        missing_patch_files,
        duplicate_patch_entries):
    """Formats human-readable error items for patch inventory mismatches."""
    error_items = []
    for patch_filename in undocumented_patch_files:
        error_items.append(
            f'patches/{patch_filename}: present in patches/ but missing from '
            f'{_README_FILENAME}')
    for patch_filename in missing_patch_files:
        error_items.append(
            f'{patch_filename}: listed in {_README_FILENAME} but missing from '
            'patches/')
    for patch_filename in duplicate_patch_entries:
        error_items.append(
            f'{patch_filename}: listed more than once in {_README_FILENAME}')
    return error_items


def CheckPatchInventoryInSync(input_api, output_api):
    """Verifies top-level patches/*.patch files match README.chromium 1-to-1.

    Catches two failure modes that previously occurred during rolls
    (https://crbug.com/568001675):
      1. A patch is documented in README.chromium (and applied to src/), but the
         patches/NNNN-name.patch file was never committed.
      2. A patch file exists in patches/, but its README.chromium entry is
         missing or misspelled.

    Args:
      input_api: The depot_tools presubmit InputApi instance.
      output_api: The depot_tools presubmit OutputApi instance.

    Returns:
      A list containing a single PresubmitError if README.chromium is missing,
      lacks the patch description section, or disagrees with patches/*.patch;
      otherwise an empty list.
    """
    readme_lines = _ReadReadmeLines(input_api)
    if readme_lines is None:
        return [
            output_api.PresubmitError(
                f'{_README_FILENAME} is missing from //third_party/protobuf.')
        ]

    documented_patch_entries = _ParseDocumentedPatchEntries(
        input_api, readme_lines)
    if documented_patch_entries is None:
        return [
            output_api.PresubmitError(
                f'{_README_FILENAME} is missing the '
                f'"{_PATCHES_SECTION_HEADER}" section.')
        ]

    top_level_files = _ListTopLevelFilesInPatchesDirectory(input_api)
    patch_files_on_disk = {
        filename for filename in top_level_files if filename.endswith('.patch')
    }
    documented_patch_set = set(documented_patch_entries)

    undocumented_patch_files = sorted(
        patch_files_on_disk - documented_patch_set)
    missing_patch_files = sorted(
        documented_patch_set - patch_files_on_disk)
    duplicate_patch_entries = _FindDuplicateEntries(documented_patch_entries)

    error_items = _FormatPatchInventorySyncItems(
        undocumented_patch_files, missing_patch_files, duplicate_patch_entries)
    if not error_items:
        return []

    return [
        output_api.PresubmitError(
            f'Top-level patches/*.patch files and "{_PATCHES_SECTION_HEADER}" '
            f'in {_README_FILENAME} are out of sync:',
            items=error_items,
        )
    ]


def CheckCompanionMarkdownFiles(input_api, output_api):
    """Verifies companion patches/*.md files and README.chromium references.

    Some complex patches carry a longer companion design note in
    patches/NNNN-name.md referenced from README.chromium. This check ensures:
      1. Every 'patches/NNNN-name.md' mentioned in README.chromium exists in
         //third_party/protobuf/patches/.
      2. Every top-level patches/NNNN-name.md file has a corresponding
         patches/NNNN-name.patch file (so dropping a patch does not leave an
         orphaned companion markdown file behind).

    Args:
      input_api: The depot_tools presubmit InputApi instance.
      output_api: The depot_tools presubmit OutputApi instance.

    Returns:
      A list containing a PresubmitError if any referenced markdown file is
      missing or any top-level markdown file lacks a matching .patch file;
      otherwise an empty list.
    """
    readme_lines = _ReadReadmeLines(input_api)
    if readme_lines is None:
        return []

    referenced_markdown_files = _ParseReferencedCompanionMarkdownFiles(
        input_api, readme_lines)
    top_level_files = _ListTopLevelFilesInPatchesDirectory(input_api)
    patch_files_on_disk = {
        filename for filename in top_level_files if filename.endswith('.patch')
    }
    markdown_files_on_disk = {
        filename for filename in top_level_files if filename.endswith('.md')
    }

    missing_markdown_files = sorted(
        referenced_markdown_files - markdown_files_on_disk)
    orphan_markdown_files = sorted(
        markdown_filename for markdown_filename in markdown_files_on_disk
        if (markdown_filename.removesuffix('.md') + '.patch')
        not in patch_files_on_disk)

    error_items = []
    for markdown_filename in missing_markdown_files:
        error_items.append(
            f'patches/{markdown_filename}: referenced in {_README_FILENAME} '
            'but does not exist')
    for markdown_filename in orphan_markdown_files:
        matching_patch_name = markdown_filename.removesuffix('.md') + '.patch'
        error_items.append(
            f'patches/{markdown_filename}: has no matching '
            f'patches/{matching_patch_name} file')

    if not error_items:
        return []

    return [
        output_api.PresubmitError(
            'Companion markdown files in patches/ are out of sync:',
            items=error_items,
        )
    ]


def CheckNoPatchRejectOrOrigFiles(input_api, output_api):
    """Checks that no *.rej or *.orig files exist under //third_party/protobuf.

    Running `patch -p1` leaves *.rej files when hunks fail and *.orig backup
    files when hunks apply with offset or fuzz. Because *.orig is matched by
    Chromium's root .gitignore, leftover backup files are invisible to
    `git status`. Walking the directory tree catches both tracked and untracked
    leftovers.

    Args:
      input_api: The depot_tools presubmit InputApi instance.
      output_api: The depot_tools presubmit OutputApi instance.

    Returns:
      A list containing a PresubmitError listing any *.rej or *.orig files found
      under //third_party/protobuf, or an empty list if none exist.
    """
    protobuf_directory = input_api.os_path.abspath(
        input_api.PresubmitLocalPath())
    if not input_api.os_path.isdir(protobuf_directory):
        return []

    leftover_files = set()
    for current_root, subdirectories, filenames in input_api.os_walk(
            protobuf_directory):
        subdirectories[:] = [
            directory for directory in subdirectories
            if directory not in ('.git', '__pycache__')
        ]
        for filename in filenames:
            if _IsPatchRejectOrBackupFile(filename):
                full_path = input_api.os_path.join(current_root, filename)
                relative_path = input_api.os_path.relpath(
                    full_path, protobuf_directory).replace('\\', '/')
                leftover_files.add(relative_path)

    if not leftover_files:
        return []

    return [
        output_api.PresubmitError(
            'Found leftover patch .rej/.orig files under '
            '//third_party/protobuf:',
            items=sorted(leftover_files),
        )
    ]


def CheckSourceModifiedWithoutPatch(input_api, output_api):
    """Warns when src/ or python/ files change without a top-level patch change.

    If a developer edits files under //third_party/protobuf/src/ or
    //third_party/protobuf/python/ and forgets to regenerate or add a patch in
    //third_party/protobuf/patches/, the next upstream roll will overwrite the
    change. Because full upstream rolls and some cleanups legitimately touch
    src/ or python/ without touching patches/, this check emits a prompt warning
    rather than a blocking error.

    Files written by gen_extra_chromium_files.py (_BOOTSTRAP_GENERATED_FILES)
    and upstream's own patches/protobuf_vNN/ subdirectories are excluded.

    Args:
      input_api: The depot_tools presubmit InputApi instance.
      output_api: The depot_tools presubmit OutputApi instance.

    Returns:
      A list containing a PresubmitPromptWarning if non-generated src/ or
      python/ files were modified without any top-level patches/*.patch change,
      or an empty list otherwise.
    """
    modified_source_files = []
    has_modified_top_level_patch = False

    for affected_file in input_api.AffectedFiles(include_deletes=True):
        relative_path = _RelativePathInProtobuf(input_api, affected_file)
        if _IsTopLevelPatchFile(relative_path):
            has_modified_top_level_patch = True
        elif _IsProtobufSourceFileRequiringPatch(relative_path):
            modified_source_files.append(relative_path)

    if not modified_source_files or has_modified_top_level_patch:
        return []

    return [
        output_api.PresubmitPromptWarning(
            'Files under //third_party/protobuf/{src,python}/ were modified '
            'without updating any top-level file in patches/. Local changes to '
            'protobuf sources must be saved as a patch in patches/ so the next '
            'roll does not silently drop them (if this is an upstream roll or '
            'intentional cleanup, you may continue):',
            items=sorted(modified_source_files),
        )
    ]


def CheckPresubmitUnitTests(input_api, output_api):
    """Runs all *_test.py unit tests in //third_party/protobuf."""
    return input_api.canned_checks.RunUnitTestsInDirectory(
        input_api,
        output_api,
        input_api.PresubmitLocalPath(),
        files_to_check=[r'^.+_test\.py$'],
    )


def _RunAllProtobufChecks(input_api, output_api):
    """Runs all synchronous //third_party/protobuf checks without subprocesses.

    Provided for unit tests so they can exercise the full check suite in-process
    without recursively invoking CheckPresubmitUnitTests.
    """
    results = []
    results.extend(CheckPatchInventoryInSync(input_api, output_api))
    results.extend(CheckCompanionMarkdownFiles(input_api, output_api))
    results.extend(CheckNoPatchRejectOrOrigFiles(input_api, output_api))
    results.extend(CheckSourceModifiedWithoutPatch(input_api, output_api))
    return results
